// Qué hace: relaciona el comentario con la visita y arma la respuesta.
// La persona contestó al mensaje "¿Qué podemos mejorar?". Buscamos SU visita más reciente
// que ya tiene puntaje bajo (<= csat_comentario_max) y todavía no tiene comentario.
const msg = $('Telegram Trigger').first().json.message;
const cfg = {};
for (const it of $('Leer config (comentario)').all()) { if (it.json.clave) cfg[it.json.clave] = String(it.json.valor); }
const maxCom = parseInt(cfg.csat_comentario_max || '3');
const umbralAlerta = parseInt(cfg.csat_alerta_max || '2');
const comentario = String(msg.text || '').trim().slice(0, 500);
const filas = $('Buscar visitas del chat').all().map(i => i.json).filter(f => f && f.id);
const cand = filas
  .filter(f => String(f.csat_score ?? '').trim() !== '' && Number(f.csat_score) <= maxCom && String(f.csat_comentario ?? '').trim() === '')
  .sort((a, b) => String(b.creado_en).localeCompare(String(a.creado_en)))[0];
let guardar = false, respuesta;
if (!comentario) respuesta = 'Solo puedo guardar comentarios escritos. Si querés, respondé al mensaje anterior con un texto.';
else if (!cand) respuesta = 'Ya tenemos tu comentario, ¡gracias!';
else { guardar = true; respuesta = '¡Gracias por contarnos! Lo vamos a tener en cuenta.'; }
const score = cand ? Number(cand.csat_score) : null;
const alertar = guardar && score <= umbralAlerta;
const texto = alertar ? [
  '💬 Comentario de una encuesta con puntaje bajo (' + score + ' de 5)',
  'Visita: ' + cand.id,
  'Quién: ' + (cand.nombre || '-') + ' (' + (cand.contacto || 'sin contacto') + ')',
  '',
  'Dijo: ' + comentario
].join('\n') : '';
return [{ json: { guardar, respuesta, id: cand ? cand.id : '', comentario, chat_id: msg.chat.id, alertar, texto, staff_chat_id: cfg.staff_chat_id || '' } }];

// Lee el toque del botón directo del trigger (el nodo anterior solo contestó el callback).
const cb = $('Telegram Trigger').first().json.callback_query;
const p = String(cb.data || '').split('|');
const score = Number(p[2]);
// Texto con el que queda la encuesta una vez respondida (sin botones).
// Es fijo a propósito: si llegan varios toques a la vez, todos intentan la MISMA edición
// y Telegram solo acepta la primera ("message is not modified" para el resto).
const MARCA = '✅ Calificación registrada.';
const original = String((cb.message && cb.message.text) || '');
const texto_cerrado = original.includes(MARCA) ? original : (original ? original + '\n\n' + MARCA : MARCA);
return [{ json: {
  valido: p[0] === 'csat' && p.length === 3 && Number.isInteger(score) && score >= 1 && score <= 5,
  id: p[1], score: score, query_id: cb.id,
  chat_id: cb.message.chat.id, message_id: cb.message.message_id,
  texto_cerrado: texto_cerrado
} }];

// Decide si hay que alertar al staff por un puntaje bajo.
// Alerta solo si: la visita existe, el puntaje es <= csat_alerta_max (hoja config)
// y la fila NO tenía puntaje antes. Así, si la persona toca otro botón después,
// no se manda una segunda alerta.
const cfg = {};
for (const it of $('Leer config').all()) { if (it.json.clave) cfg[it.json.clave] = String(it.json.valor); }
const umbral = parseInt(cfg.csat_alerta_max || '2');
const cb = $('Parsear callback').first().json;
const fila = $('Buscar visita').first().json || {};
const yaTeniaPuntaje = String(fila.csat_score ?? '').trim() !== '';
const alertar = !!fila.id && cb.score <= umbral && !yaTeniaPuntaje;
// Pedir comentario: puntaje <= csat_comentario_max (config) y primera vez que responde.
const maxCom = parseInt(cfg.csat_comentario_max || '3');
const pedirComentario = !!fila.id && cb.score <= maxCom && !yaTeniaPuntaje;
const texto = [
  '⚠️ Encuesta con puntaje bajo: ' + cb.score + ' de 5',
  'Visita: ' + (fila.id || cb.id),
  'Quién: ' + (fila.nombre || '-') + ' (' + (fila.contacto || 'sin contacto') + ')',
  'Fecha de la visita: ' + (fila.fecha || '-') + ' ' + (fila.hora || ''),
  'Personas: ' + (fila.personas || '-') + ' · Motivo: ' + (fila.motivo || '-'),
  '',
  'Conviene contactarla para entender qué pasó.'
].join('\n');
return [{ json: { pedir_comentario: pedirComentario, chat_id: cb.chat_id, alertar, texto, staff_chat_id: cfg.staff_chat_id || '', score: cb.score, umbral, ya_tenia_puntaje: yaTeniaPuntaje } }];
